// ─── ESTRAI AWB DAL SUBJECT (12 CIFRE) ───
const subject = $input.item.json.subject || '';
const awbMatch = subject.match(/(\d{12})/);
const awb = awbMatch ? awbMatch[1] : null;

// ─── DATA ODIERNA PER CARTELLA ───
const now = new Date();
const yearMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
const today = now.toISOString().split('T')[0];

// ─── PATH SHAREPOINT ───
const folderPath = awb
  ? `/Dogana/FedEx/${yearMonth}/${awb}`
  : `/Dogana/FedEx/${yearMonth}/NOAWB_${Date.now()}`;

return {
  awb,
  awbValid: awb !== null && awb.length === 12,
  yearMonth,
  today,
  folderPath,
  emailSubject: subject,
  emailFrom: $input.item.json.from,
  emailId: $input.item.json.id,
  conversationId: $input.item.json.conversationId,
  attachments: $input.item.json.attachments || []
};

// Passa dati dalla email trigger + info cartella creata
const prev = $('Code - Estrai AWB e Inizializza Variabili').first().json;
return {
  ...prev,
  spFolderId: $input.item.json.id,
  spFolderWebUrl: $input.item.json.webUrl
};

// ─── CLASSIFICA E PREPARA ALLEGATI ───
const attachments = $input.item.json.attachments || [];
const result = [];

for (const att of attachments) {
  const name = (att.name || '').toUpperCase();
  let docType = 'OTHER';

  if (name.includes('CI') || name.includes('COMMERCIAL_INVOICE') || name.includes('COMMERCIAL INVOICE')) {
    docType = 'CI';
  } else if (name.includes('PL') || name.includes('PACKING_LIST') || name.includes('PACKING LIST')) {
    docType = 'PL';
  } else if (name.includes('AWB') || name.includes('AIR_WAYBILL') || name.includes('AIRWAYBILL')) {
    docType = 'AWB';
  }

  result.push({
    ...att,
    docType,
    spFileName: `${docType}_${att.name}`
  });
}

const meta = $('Code - Merge Info Cartella').first().json;
return result.map(att => ({ ...meta, attachment: att }));

// Dopo il loop, raccogli tutti gli allegati classificati
const allItems = $input.all();
const meta = allItems[0].json;

const ci = allItems.find(i => i.json.attachment?.docType === 'CI');
const pl = allItems.find(i => i.json.attachment?.docType === 'PL');
const awbDoc = allItems.find(i => i.json.attachment?.docType === 'AWB');

return {
  ...meta,
  ciFile: ci ? ci.json.attachment : null,
  plFile: pl ? pl.json.attachment : null,
  awbDocFile: awbDoc ? awbDoc.json.attachment : null,
  ciFound: !!ci,
  plFound: !!pl
};

