// ─── PARSE RISPOSTA PL DA GPT-4o ───
const raw = $input.item.json.choices?.[0]?.message?.content || '{}';
let plData = {};
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  plData = JSON.parse(cleaned);
} catch(e) {
  plData = { parseError: true, rawResponse: raw };
}

const meta = $('Code - Raccogli Documenti Classificati').first().json;
return {
  ...meta,
  pl: {
    TotalCartons: parseInt(plData.TotalCartons) || null,
    TotalNetWeight: parseFloat(plData.TotalNetWeight) || null,
    TotalGrossWeight: parseFloat(plData.TotalGrossWeight) || null,
    TotalVolume: parseFloat(plData.TotalVolume) || null,
    HSCode: plData.HSCode || null,
    OriginCountry: plData.OriginCountry || null,
    parseError: plData.parseError || false
  }
};

// ─── GATE DI QUALITÀ ─────────────────────────────────────
// Combina i dati CI e PL da entrambi i rami del merge
const items = $input.all();
const ciItem = items.find(i => i.json.ci);
const plItem = items.find(i => i.json.pl);

const ci = ciItem?.json.ci || {};
const pl = plItem?.json.pl || {};
const meta = ciItem?.json || plItem?.json || {};

const checks = [];
let passed = true;

// Check 1: AWB 12 cifre
if (!meta.awbValid) {
  checks.push({ id: 'CHECK_AWB', ok: false, msg: `AWB non trovato o non valido: '${meta.awb}'` });
  passed = false;
} else {
  checks.push({ id: 'CHECK_AWB', ok: true, msg: `AWB OK: ${meta.awb}` });
}

// Check 2: TotalAmount > 0
if (!ci.TotalAmount || ci.TotalAmount <= 0) {
  checks.push({ id: 'CHECK_AMOUNT', ok: false, msg: `TotalAmount CI mancante o zero: ${ci.TotalAmount}` });
  passed = false;
} else {
  checks.push({ id: 'CHECK_AMOUNT', ok: true, msg: `Amount OK: ${ci.TotalAmount} ${ci.Currency}` });
}

// Check 3: HSCode CI vs PL (solo se PL presente)
if (meta.plFound && pl.HSCode && ci.HSCode) {
  const hsMatch = ci.HSCode.replace(/\s/g, '') === pl.HSCode.replace(/\s/g, '');
  if (!hsMatch) {
    checks.push({ id: 'CHECK_HSCODE', ok: false, msg: `HSCode CI (${ci.HSCode}) != HSCode PL (${pl.HSCode})` });
    passed = false;
  } else {
    checks.push({ id: 'CHECK_HSCODE', ok: true, msg: `HSCode OK: ${ci.HSCode}` });
  }
} else {
  checks.push({ id: 'CHECK_HSCODE', ok: true, msg: 'HSCode PL non disponibile, check saltato' });
}

// Check 4: OriginCountry CI vs PL (solo se PL presente)
if (meta.plFound && pl.OriginCountry && ci.OriginCountry) {
  const origMatch = ci.OriginCountry.toUpperCase() === pl.OriginCountry.toUpperCase();
  if (!origMatch) {
    checks.push({ id: 'CHECK_ORIGIN', ok: false, msg: `OriginCountry CI (${ci.OriginCountry}) != PL (${pl.OriginCountry})` });
    passed = false;
  } else {
    checks.push({ id: 'CHECK_ORIGIN', ok: true, msg: `Origin OK: ${ci.OriginCountry}` });
  }
} else {
  checks.push({ id: 'CHECK_ORIGIN', ok: true, msg: 'OriginCountry PL non disponibile, check saltato' });
}

// Check 5: CI trovata
if (!meta.ciFound) {
  checks.push({ id: 'CHECK_CI_FOUND', ok: false, msg: 'Nessun file CI identificato negli allegati' });
  passed = false;
} else {
  checks.push({ id: 'CHECK_CI_FOUND', ok: true, msg: 'CI trovata' });
}

const failedChecks = checks.filter(c => !c.ok);
const exceptionSummary = failedChecks.map(c => `• [${c.id}] ${c.msg}`).join('\n');

return {
  ...meta,
  ci,
  pl,
  qualityChecks: checks,
  qualityPassed: passed,
  failedChecks,
  exceptionSummary
};

// ─── PREPARA DATI PER TEMPLATE WORD ───
const data = $('IF - Quality Gate Superato?').first().json;
const ci = data.ci || {};
const today = data.today;

// Importa dati azienda da env o hardcode
const importerCompanyName = process.env.IMPORTER_COMPANY_NAME || 'Redmade S.r.l.';
const importerVAT          = process.env.IMPORTER_VAT           || 'IT12345678901';
const importerAddress      = process.env.IMPORTER_ADDRESS       || 'Via Esempio 1, 20100 Milano (MI)';

return {
  ...data,
  templateData: {
    ImporterCompanyName: importerCompanyName,
    ImporterVAT:         importerVAT,
    ImporterAddress:     importerAddress,
    AWB:                 data.awb || '',
    HSCode:              ci.HSCode || '',
    OriginCountry:       ci.OriginCountry || '',
    InvoiceNumber:       ci.InvoiceNumber || '',
    InvoiceTotal:        String(ci.TotalAmount || ''),
    Currency:            ci.Currency || 'USD',
    SupplierName:        ci.SellerName || '',
    DateToday:           today
  }
};

// ─── POPOLA TEMPLATE WORD CON FIND & REPLACE ───
// Legge il DOCX come binary e sostituisce i placeholder {{CAMPO}}
// Nota: per Content Controls via Graph API usare endpoint /populate
// Qui usiamo la libreria docx-templates via HTTP call a funzione Azure
// oppure un approccio semplificato con placeholder testuali {{CAMPO}}

const templateData = $('Code - Prepara Dati Template').first().json.templateData;
const meta = $('Code - Prepara Dati Template').first().json;

// Restituisce i dati per la chiamata Graph API Word Online
return {
  ...meta,
  wordPopulatePayload: {
    docxTemplateUrl: `/Dogana/Templates/LetteraSdoganamento_Template.docx`,
    outputFileName: `LetteraSdoganamento_${meta.awb}.docx`,
    outputPath: `${meta.folderPath}/LetteraSdoganamento_${meta.awb}.docx`,
    fields: templateData
  }
};

// ─── PREPARA CORPO REPLY A FEDEX ───
const data = $('Code - Prepara Dati Template').first().json;
const pdfPath = data.wordPopulatePayload?.outputPath?.replace('.docx', '.pdf');

return {
  ...data,
  replyBody: `Buongiorno,

in riferimento alla spedizione AWB ${data.awb}, in allegato trasmettiamo la seguente documentazione per lo sdoganamento:

• Fattura Commerciale (Commercial Invoice)
• Packing List${data.plFound ? '' : ' (non disponibile)'}
• Lettera di Sdoganamento

Restiamo a disposizione per qualsiasi ulteriore informazione.

Cordiali saluti,
${process.env.IMPORTER_COMPANY_NAME || 'Redmade S.r.l.'}`,
  pdfSPPath: pdfPath
};

